import fs from "node:fs";

/**
 * Two ways to build the docs site:
 * - Vercel (the live site, https://dx-design-system.vercel.app): plain `next build`, served at the domain root.
 * - Static export for tests: `npm run build:pages` sets PAGES_BASE_PATH and writes out/, which
 *   Playwright serves at http://localhost:4173/dx-design-system/. (GitHub Pages hosting was retired in v4.)
 * trailingSlash stays on for both, so every URL matches the sidebar links (/components/button/).
 */
const base = process.env.PAGES_BASE_PATH;
// v3 → v4 URLs (generated by scripts/build-docs-data.mjs). Vercel serves them as permanent redirects; the static export has no server, so tests check the map instead.
const v3 = JSON.parse(fs.readFileSync(new URL("./src/site/redirects.json", import.meta.url), "utf8"));

/** @type {import("next").NextConfig} */
export default {
  reactStrictMode: true,
  trailingSlash: true,
  ...(base === undefined && {
    async redirects() {
      return v3.map(([source, destination]) => ({ source, destination, permanent: true }));
    },
  }),
  ...(base !== undefined && {
    output: "export",
    basePath: base,
    images: { unoptimized: true },
  }),
};
